    "category": "performance",
    "content": "The `queue.sort()` call inside the while loop, combined with `queue.shift()` (which is O(n) for arrays), makes the topological sort O(n² log n) instead of the optimal O((V+E) log V). Using a min-heap (priority queue) to track the zero-in-degree nodes would avoid both the O(n) shift and the repeated full O(n log n) re-sort on every iteration. Additionally, the initial `.sort()` on `ids.filter(...)` is redundant since `ids` is already ordered by the SQL `ORDER BY id`.",
    "existing_code": "  const queue = ids.filter((id) => indeg.get(id) === 0).sort();
  const order: string[] = [];
  while (queue.length > 0) {
    const n = queue.shift()!;
    order.push(n);
    for (const m of adj.get(n)!.sort()) {
      indeg.set(m, indeg.get(m)! - 1);
      if (indeg.get(m) === 0) queue.push(m);
    }
    queue.sort();
  }",
    "severity": "medium",
    "path": "src/plan.ts",
    "suggestion_code": "  // Use a sorted array or min-heap to avoid repeated full sorts
  const queue = ids.filter((id) => indeg.get(id) === 0);
  const order: string[] = [];
  while (queue.length > 0) {
    const n = queue.shift()!;
    order.push(n);
    for (const m of adj.get(n)!.sort()) {
      indeg.set(m, indeg.get(m)! - 1);
      if (indeg.get(m) === 0) {
        // Insert m into queue maintaining sorted order (binary search + splice)
        const idx = queue.findIndex((x) => x >= m);
        if (idx === -1) queue.push(m);
        else queue.splice(idx, 0, m);
      }
    }
  }"
  },
