export async function syncPrs(db: Database, list: () => Promise<PrRow[]>): Promise<{ rows: number }> {
  let rows: PrRow[];
  try {
    rows = await list();
  } catch (err) {
    throw new Error(`Failed to fetch PR rows for sync: ${err instanceof Error ? err.message : String(err)}`, { cause: err });
  }
  const tx = db.transaction(() => { for (const r of rows) upsertPr(db, r); });
  try {
    tx();
  } catch (err) {
    throw new Error(`Failed to upsert PR rows in transaction: ${err instanceof Error ? err.message : String(err)}`, { cause: err });
  }
  return { rows: rows.length };
}

